head.script:
// 테스트 설명, 유효성 값 설정
//  _2 : columnInfo 파라미터를 Column ID(문자열)로 지정하는 분리 샘플 (_1 은 인덱스 지정)
scwin.tData = {
    "description" : "[gridView > M > setImageSrc]<br/>inputType='textImage' 인 Body Column 의 imageSrc 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 imageSrc 속성을 설정하려는 Body Column 의 ID 를 설정할 수 있어야 합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 파라미터 기본 선택값 설정 (정적 select1 은 초기 selectedIndex 미적용)
    par_columnInfo.setSelectedIndex(2);
    par_src.setSelectedIndex(0);

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - Column 구성(ID) : name(text) / hid(textImage, 숨김) / timg(textImage) / cimg(textImage, Row 1 Cell imageSrc 설정)
//    · 숨김 Column 과 Cell 단위 imageSrc 선설정은 _1 과 동일한 화면을 만들기 위한 구성이며 _2 의 검증 대상이 아님
//    · cimg 의 Row 1 Cell imageSrc 는 timg 와 cimg 를 구분하는 표식이 되어, Column ID 가 올바른 Column 으로
//      해석되었는지 결과창에서 식별할 수 있게 해줌
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Body Column ID 구성 : name(text) / hid(textImage, viewType=icon, 숨김) / timg(textImage, viewType=icon) / cimg(textImage, viewType=icon, Row 1 만 Cell imageSrc 선설정)\n[절차] columnInfo 에 Column ID 를 선택하고 src 를 선택한 뒤 setImageSrc 버튼을 클릭하세요.\n[확인] 지정한 ID 의 Column 에만 이미지가 적용되는지 그리드 화면과 결과창의 Row 별 표시 텍스트 / 이미지 경로로 확인하세요. cimg 는 Row 1 에 Cell 단위 이미지가 미리 설정되어 있어 timg 와 구분됩니다."', '', 'label1');

    // === 바인딩 DataList(dlt_bind) ===
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="hid" name="hid" dataType="text"></w2:column>';
    strDlt += '<w2:column id="timg" name="timg" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cimg" name="cimg" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "name": "John", "hid": "H0", "timg": "수정", "cimg": "삭제" },
        { "name": "Jane", "hid": "H1", "timg": "수정", "cimg": "삭제" },
        { "name": "Mike", "hid": "H2", "timg": "수정", "cimg": "삭제" },
        { "name": "Amy",  "hid": "H3", "timg": "수정", "cimg": "삭제" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // target 그리드 직접 구성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:660px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setImageSrc test grid"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol1" value="name (text)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="hid (숨김)"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" id="hcol3" value="timg (textImage)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="cimg (Row 1 Cell 설정)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="textImage" viewType="icon" id="hid" dataList="hid"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="textImage" viewType="icon" id="timg" dataList="timg"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="textImage" viewType="icon" id="cimg" dataList="cimg"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // _1 과 동일한 화면 구성 (숨김 Column / Cell 단위 imageSrc 선설정)
    target1.setColumnVisible(1, false);
    target1.setCellImageSrc(1, 3, "/cm/images/base/ico_fav_on.svg");
}



// Body Cell 의 표시 텍스트 / 이미지 경로 확인
scwin.getCellImgInfo = function (rowIndex, colIndex) {
    let cellEl = document.querySelector("td[id*='target1_cell_" + rowIndex + "_" + colIndex + "']");
    if (!cellEl) {
        return "(Cell 없음)";
    }
    let imgEl = cellEl.querySelector("img");
    let src = (imgEl && imgEl.getAttribute("src")) ? imgEl.getAttribute("src") : "(이미지 미표시)";
    return cellEl.textContent + " / " + src;
}



// setImageSrc 실행 : columnInfo 를 Column ID(문자열)로 지정하여 Body Column 의 imageSrc 를 설정하고,
//                    쌍이 되는 get 메소드가 없으므로 해당 Column 전체 Cell 의 IMG 요소를 DOM 에서 조회하여 설정 결과를 확인
scwin.btn_setImageSrc_onclick = function () {
    // _2 : columnInfo 를 Column ID(문자열)로 그대로 전달 (Number 변환하지 않음)
    let columnInfo = par_columnInfo.getText();
    let src = par_src.getText();

    target1.setImageSrc(columnInfo, src);

    // 지정한 Column ID 에 대응하는 Body Column 전체 Cell 의 표시 텍스트 / 이미지 경로 수집
    let colIndex = ["name", "hid", "timg", "cimg"].indexOf(columnInfo);
    let detail = [];
    for (let i = 0; i < 4; i++) {
        detail.push("[Row " + i + "] " + scwin.getCellImgInfo(i, colIndex));
    }

    wf_body_bottom.getObj("scwin").setReturnValue("setImageSrc('" + columnInfo + "', '" + src + "') 호출 후 Column 전체 Cell (표시 텍스트 / 이미지 경로) : " + detail.join(", "));
}
